import{At as e,Et as t,dt as n,ft as r,lt as i,n as a,ot as o,ut as s}from"./chunks/framework.8UxoGp64.js";var c=JSON.parse(`{"title":"主题设计器","description":"","frontmatter":{"sidebar":false,"aside":false,"pageClass":"xh-designer-page"},"headers":[],"relativePath":"design/theme-designer.md","filePath":"design/theme-designer.md","lastUpdated":1791467958000}`),l={name:`design/theme-designer.md`};function u(a,c,l,u,d,f){let p=e(`XhThemeDesigner`);return t(),i(`div`,null,[c[0]||=o(`h1`,{id:`主题设计器`,tabindex:`-1`},[n(`主题设计器 `),o(`a`,{class:`header-anchor`,href:`#主题设计器`,"aria-label":`Permalink to “主题设计器”`},`​`)],-1),c[1]||=o(`p`,null,`从一套预设出发，或者自己挑品牌色，再定明暗、密度、对比度与圆角，下方整面真实组件随之实时变化；满意后复制最下面的 CSS 与接入代码放进项目。设置只保存在当前浏览器里。`,-1),r(p),c[2]||=s(`<h2 id="能改什么" tabindex="-1">能改什么 <a class="header-anchor" href="#能改什么" aria-label="Permalink to “能改什么”">​</a></h2><table tabindex="0"><thead><tr><th>设置</th><th>改的是</th><th>项目里怎么用</th></tr></thead><tbody><tr><td>品牌色</td><td>由种子色派生的整套 <code>--xh-color-brand-50…950</code> 原语</td><td>导出的 <code>[data-brand]</code> 取值块，或运行时 <code>registerBrand</code></td></tr><tr><td>明暗</td><td><code>data-theme</code></td><td>视觉环境控制器的 <code>mode</code></td></tr><tr><td>密度</td><td><code>data-density</code></td><td>控制器的 <code>density</code></td></tr><tr><td>对比度</td><td><code>data-contrast</code></td><td>控制器的 <code>contrast</code></td></tr><tr><td>圆角</td><td>原始阶梯 <code>--xh-radius-sm / md / lg</code></td><td>导出的 <code>:root</code> 覆盖</td></tr></tbody></table><p>预设只是上面五项的一组取值，选中后照样可以逐项微调；与哪套预设完全一致，哪套就显示为选中。</p><p>品牌色只取种子的色相与彩度，明度曲线沿用基线，所以换任何种子，语义层（实心按钮、链接、选中态）的对比度保证都不变；种子本身的明暗不会被原样搬进来。圆角改的是原始阶梯，控件、表面、浮层三档形状语义跟着走，组件之间的层次关系保持不变。</p><h2 id="接入" tabindex="-1">接入 <a class="header-anchor" href="#接入" aria-label="Permalink to “接入”">​</a></h2><p>把「CSS」一栏放进全局样式，或者只用「TypeScript」一栏在运行时注册品牌：两者给出的品牌色是同一套。明暗、密度与对比度属于视觉环境，按<a href="./../guide/theme#八轴视觉环境运行时">设计令牌与主题</a>里的控制器提交，Vue 与 React 也可以经 <code>XhConfigProvider</code> 传入。</p><p>预览区本身就是一个局部视觉环境：它用 <code>XhConfigProvider</code> 的同一套机制把设置写到自己的根元素上，下拉、日期面板这类渲染到预览区之外的浮层也会带上同样的设置。项目里把控制器挂在根元素上，整站随之生效。</p>`,7)])}var d=a(l,[[`render`,u]]);export{c as __pageData,d as default};